import { describe, expect, it } from "vitest";
import {
  isWebhookEvent,
  parseWebhook,
  signWebhookPayload,
  verifyWebhookSignature,
  WebhookVerificationError,
  WEBHOOK_TOLERANCE_SECONDS,
} from "./index.js";
import vectors from "./testdata/webhook_vectors.json" with { type: "json" };

// Generated by the normative Go verifier. On a mismatch, fix the TypeScript —
// never regenerate the vectors from it.
interface Vector {
  name: string;
  secret: string;
  body: string;
  header: string;
  now: number;
  expected: "ok" | "malformed" | "stale" | "mismatch";
}

const outcome = async (v: Vector, payload: string | Uint8Array = v.body): Promise<string> => {
  try {
    await verifyWebhookSignature({
      payload,
      header: v.header,
      secret: v.secret,
      now: new Date(v.now * 1000),
    });
    return "ok";
  } catch (err) {
    if (err instanceof WebhookVerificationError) return err.reason;
    throw err;
  }
};

describe("webhook signature vectors", () => {
  it("uses the reference tolerance", () => {
    expect(vectors.tolerance_seconds).toBe(WEBHOOK_TOLERANCE_SECONDS);
  });

  it("covers every outcome", () => {
    const seen = new Set((vectors.vectors as Vector[]).map((v) => v.expected));
    expect([...seen].sort()).toEqual(["malformed", "mismatch", "ok", "stale"]);
  });

  for (const v of vectors.vectors as Vector[]) {
    it(`${v.name} → ${v.expected}`, async () => {
      expect(await outcome(v)).toBe(v.expected);
      // Raw bytes and raw text must agree.
      expect(await outcome(v, new TextEncoder().encode(v.body))).toBe(v.expected);
    });
  }
});

describe("verifyWebhookSignature", () => {
  const secret = "whsec_test";
  const body = '{"id":"evt_1","type":"ping","created_at":"2026-11-17T09:05:26Z","api_version":"v1","customer_id":"org_x","data":{"endpoint_id":"whe_1","message":"ping"}}';

  it("treats a missing header as malformed", async () => {
    await expect(
      verifyWebhookSignature({ payload: body, header: undefined, secret }),
    ).rejects.toMatchObject({ reason: "malformed" });
  });

  it("accepts any of several secrets", async () => {
    const header = await signWebhookPayload("whsec_old", body);
    await verifyWebhookSignature({ payload: body, header, secret: ["whsec_new", "whsec_old"] });
  });

  it("honours a custom tolerance", async () => {
    const header = await signWebhookPayload(secret, body, 1_000);
    await expect(
      verifyWebhookSignature({ payload: body, header, secret, now: new Date(1_060_000), toleranceSeconds: 30 }),
    ).rejects.toMatchObject({ reason: "stale" });
    await verifyWebhookSignature({ payload: body, header, secret, now: new Date(1_060_000), toleranceSeconds: 90 });
  });

  it("signWebhookPayload agrees with the reference signer", async () => {
    const v = (vectors.vectors as Vector[]).find((x) => x.name === "rotation_new_first")!;
    const t = Number(/t=(\d+)/.exec(v.header)![1]);
    const old = (vectors.vectors as Vector[]).find((x) => x.name === "rotation_old_secret_still_verifies")!;
    expect(await signWebhookPayload([v.secret, old.secret], v.body, t)).toBe(v.header);
  });

  it("parseWebhook verifies, then parses and narrows", async () => {
    const header = await signWebhookPayload(secret, body);
    const event = await parseWebhook({ payload: body, header, secret });
    expect(event.id).toBe("evt_1");
    expect(isWebhookEvent(event, "ping")).toBe(true);
    if (isWebhookEvent(event, "ping")) expect(event.data.endpoint_id).toBe("whe_1");
    expect(isWebhookEvent(event, "account.flagged")).toBe(false);
  });

  it("parseWebhook never parses an unverified body", async () => {
    const header = await signWebhookPayload("whsec_other", body);
    await expect(parseWebhook({ payload: body, header, secret })).rejects.toBeInstanceOf(
      WebhookVerificationError,
    );
    await expect(
      parseWebhook({ payload: "not json", header: await signWebhookPayload("whsec_other", "not json"), secret }),
    ).rejects.toMatchObject({ reason: "mismatch" });
  });

  it("passes an event type it does not know through", async () => {
    const future = JSON.stringify({ id: "evt_2", type: "account.something_new", data: {} });
    const event = await parseWebhook({ payload: future, header: await signWebhookPayload(secret, future), secret });
    expect(event.type).toBe("account.something_new");
  });
});
